content:
body {
  background: url('/img/bg3.png') no-repeat center center fixed;
  background-size: cover;
  -webkit-background-size: cover;
  -moz-background-size: cover;
  -o-background-size: cover;
  min-height: 100vh;
}

::before,
::after {
  box-sizing: border-box;
}

#body-wrap {
  background: rgba(255, 255, 255, 0);
  backdrop-filter: blur(0px);
  -webkit-backdrop-filter: blur(4px);
  min-height: 100vh;
}

[data-theme="dark"] #body-wrap {
  background: rgba(67, 33, 219, 0.2);
}

#page-header {
  background-color: transparent !important;
  background-image: none !important;
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

#page-header:not(.not-top-img):before {
  display: none !important;
}

#page-header:not(.not-top-img) #nav {
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

#page-header:not(.not-top-img) #nav a,
#page-header:not(.not-top-img) #nav span.site-page,
#page-header:not(.not-top-img) #nav .site-name {
  color: #ffffff !important;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

#page-header.nav-fixed #nav {
  background: rgba(255, 255, 255, 0.85) !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 2px 16px rgba(0, 0, 0, 0.12);
}

#page-header.nav-fixed #nav a,
#page-header.nav-fixed #nav span.site-page,
#page-header.nav-fixed #nav .site-name {
  color: #2c3e50 !important;
  text-shadow: none;
}

#page-header #nav {
  background: rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

[data-theme="dark"] #page-header #nav {
  background: rgba(30, 30, 30, 0.4);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.3);
}

#page-header #nav a,
#page-header #nav span.site-page,
#page-header #nav .site-name {
  color: #2c3e50;
  text-shadow: none;
}

[data-theme="dark"] #page-header #nav a,
[data-theme="dark"] #page-header #nav span.site-page,
[data-theme="dark"] #page-header #nav .site-name {
  color: #e0e0e0;
}

#page-header.nav-fixed #nav {
  background: rgba(255, 255, 255, 0.6) !important;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

[data-theme="dark"] #page-header.nav-fixed #nav {
  background: rgba(30, 30, 30, 0.7) !important;
}

#page-header #site-title,
#page-header #post-info .post-title {
  color: #1a2a3a !important;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.5) !important;
}

#page-header:not(.not-top-img) #site-title {
  color: #ffffff !important;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.5), 0 0 40px rgba(255, 255, 255, 0.15) !important;
  letter-spacing: 4px;
  font-weight: 700;
}

[data-theme="dark"] #page-header #site-title,
[data-theme="dark"] #page-header #post-info .post-title {
  color: #f0f0f0 !important;
  text-shadow: none !important;
}

#page-header:not(.not-top-img) #site-subtitle {
  color: #ffffff !important;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.5) !important;
  letter-spacing: 2px;
}

#page-header:not(.not-top-img) #scroll-down .scroll-down-effects {
  color: #ffffff !important;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
}

#page-header:not(.not-top-img)::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.05) 40%, rgba(0,0,0,0.35) 100%);
  pointer-events: none;
  z-index: 0;
}

#page-header:not(.not-top-img) #site-info {
  z-index: 1;
}

[data-theme="dark"] #page-header:not(.not-top-img) #scroll-down .scroll-down-effects {
  color: #f0f0f0 !important;
}

#page-header #post-info {
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.5);
}

[data-theme="dark"] #page-header #post-info {
  text-shadow: none;
}

main.layout {
  padding-top: 20px;
}

#recent-posts .recent-post-item,
.card-widget,
.article-sort-item,
#search-mask,
.search-dialog,
#post {
  background: rgba(255, 255, 255, 0.82) !important;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-radius: 16px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
}

[data-theme="dark"] #recent-posts .recent-post-item,
[data-theme="dark"] .card-widget,
[data-theme="dark"] .article-sort-item,
[data-theme="dark"] #search-mask,
[data-theme="dark"] .search-dialog,
[data-theme="dark"] #post {
  background: rgba(30, 30, 30, 0.82) !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

#recent-posts .recent-post-item {
  margin-bottom: 20px;
  border-radius: 16px;
  overflow: hidden;
}

.card-widget {
  border-radius: 16px;
  margin-bottom: 16px;
}

#post {
  padding: 30px 40px;
}

#footer {
  display: none !important;
}

.article-title,
.article-meta-wrap,
#aside-content .card-info .author-info-name,
#aside-content .card-info .author-info-description,
#aside-content .card-info .site-data .headline,
#aside-content .card-info .site-data .length-num {
  color: #2c3e50;
}

[data-theme="dark"] .article-title,
[data-theme="dark"] .article-meta-wrap,
[data-theme="dark"] #aside-content .card-info .author-info-name,
[data-theme="dark"] #aside-content .card-info .author-info-description,
[data-theme="dark"] #aside-content .card-info .site-data .headline,
[data-theme="dark"] #aside-content .card-info .site-data .length-num {
  color: #e0e0e0;
}

#article-container {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-radius: 0;
  padding: 0;
  box-shadow: none !important;
}

#article-container p,
#article-container li,
#article-container blockquote {
  color: #3c3c3c;
}

[data-theme="dark"] #article-container p,
[data-theme="dark"] #article-container li,
[data-theme="dark"] #article-container blockquote {
  color: #d0d0d0;
}

#article-container h1,
#article-container h2,
#article-container h3,
#article-container h4,
#article-container h5,
#article-container h6 {
  color: #1a2a3a;
}

[data-theme="dark"] #article-container h1,
[data-theme="dark"] #article-container h2,
[data-theme="dark"] #article-container h3,
[data-theme="dark"] #article-container h4,
[data-theme="dark"] #article-container h5,
[data-theme="dark"] #article-container h6 {
  color: #f0f0f0;
}

#article-container a {
  color: #2980b9;
  text-decoration: none;
  border-bottom: 1px solid rgba(41, 128, 185, 0.3);
  transition: all 0.3s ease;
}

#article-container a:hover {
  color: #1abc9c;
  border-bottom-color: #1abc9c;
}

#article-container img {
  border-radius: 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
}

#article-container pre,
#article-container code {
  border-radius: 8px;
}

.post-copyright,
.tag_share,
.pagination-post {
  background: rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-radius: 12px;
  padding: 16px 20px;
  margin-top: 20px;
}

[data-theme="dark"] .post-copyright,
[data-theme="dark"] .tag_share,
[data-theme="dark"] .pagination-post {
  background: rgba(40, 40, 40, 0.7);
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.2);
}

::-webkit-scrollbar-thumb {
  background: rgba(73, 177, 245, 0.6);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(73, 177, 245, 0.9);
}

[data-theme="dark"] ::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
}

[data-theme="dark"] ::-webkit-scrollbar-thumb {
  background: rgba(100, 100, 100, 0.6);
}

[data-theme="dark"] ::-webkit-scrollbar-thumb:hover {
  background: rgba(120, 120, 120, 0.9);
}

@media screen and (max-width: 768px) {
  #post {
    padding: 20px 16px;
    border-radius: 12px;
  }

  #body-wrap {
    background: rgba(255, 255, 255, 0.08);
  }

  [data-theme="dark"] #body-wrap {
    background: rgba(13, 13, 13, 0.15);
  }
}

#nav {
  justify-content: space-between;
}

#nav #blog-info {
  flex: none;
  flex-shrink: 0;
}

#nav #menus {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: center;
}

#nav #menus .menus_items {
  display: flex;
  align-items: center;
  justify-content: center;
}

#nav #menus .menus_items .menus_item {
  padding: 0 0 0 14px;
}

#nav #nav-right {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  gap: 20px;
}

#nav #nav-right #search-button {
  padding: 0;
}

#nav #nav-right .site-page.social-icon.search .search-text {
  display: none;
}

#nav #nav-right .nav-right-item {
  position: relative;
  display: inline-block;
  padding: 0;
  cursor: pointer;
}

#nav #nav-right .nav-right-item .site-page {
  font-size: 0.78em;
}

#nav #nav-right .nav-right-item .menus_item_child {
  position: absolute;
  right: 0;
  top: 100%;
  display: none;
  margin-top: 8px;
  padding: 0;
  width: max-content;
  background: rgba(255, 255, 255, 0.96) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25) !important;
  border-radius: 8px !important;
  z-index: 99;
}

#nav #nav-right .nav-right-item:hover .menus_item_child {
  display: block;
}

#nav #nav-right .nav-right-item .menus_item_child:before {
  position: absolute;
  top: -8px;
  left: 0;
  width: 100%;
  height: 20px;
  content: '';
}

#nav #nav-right .nav-right-item .menus_item_child li {
  list-style: none;
}

#nav #nav-right .nav-right-item .menus_item_child li a,
#page-header:not(.not-top-img) #nav #nav-right .nav-right-item .menus_item_child li a,
#page-header.nav-fixed #nav #nav-right .nav-right-item .menus_item_child li a {
  display: inline-block;
  padding: 10px 18px !important;
  width: 100%;
  color: #2c3e50 !important;
  text-shadow: none !important;
  font-size: 14px !important;
}

#nav #nav-right .nav-right-item .menus_item_child li a:hover {
  background: rgba(73, 177, 245, 0.15);
  color: #49b1f5 !important;
}

#nav #nav-right .nav-right-item .menus_item_child li:first-child a {
  border-top-left-radius: 8px;
  border-top-right-radius: 8px;
}

#nav #nav-right .nav-right-item .menus_item_child li:last-child a {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

[data-theme="dark"] #nav #nav-right .nav-right-item .menus_item_child {
  background: rgba(30, 30, 30, 0.96) !important;
}

[data-theme="dark"] #nav #nav-right .nav-right-item .menus_item_child li a {
  color: #e0e0e0 !important;
}

#nav.hide-menu #menus {
  display: none;
}

#nav.hide-menu #nav-right #toggle-menu {
  display: inline-block;
}

@media screen and (max-width: 768px) {
  #nav #menus {
    display: none;
  }
  #nav #nav-right #toggle-menu {
    display: inline-block;
  }
}

#nav .site-name {
  font-size: 22px;    /* 站点名称 */
}

#nav .menus_item .menus_item_child {
  background: rgba(255, 255, 255, 0.96) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border-radius: 8px !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25) !important;
}

#nav .menus_item .menus_item_child li a.site-page.child,
#page-header:not(.not-top-img) #nav .menus_item .menus_item_child li a.site-page.child,
#page-header.nav-fixed #nav .menus_item .menus_item_child li a.site-page.child {
  color: #2c3e50 !important;
  text-shadow: none !important;
  font-size: 14px !important;
  padding: 10px 18px !important;
}

#nav .menus_item .menus_item_child li a.site-page.child:hover,
#page-header:not(.not-top-img) #nav .menus_item .menus_item_child li a.site-page.child:hover,
#page-header.nav-fixed #nav .menus_item .menus_item_child li a.site-page.child:hover {
  background: rgba(73, 177, 245, 0.15) !important;
  color: #49b1f5 !important;
}

[data-theme="dark"] #nav .menus_item .menus_item_child {
  background: rgba(30, 30, 30, 0.96) !important;
}

[data-theme="dark"] #nav .menus_item .menus_item_child li a.site-page.child,
[data-theme="dark"] #page-header:not(.not-top-img) #nav .menus_item .menus_item_child li a.site-page.child,
[data-theme="dark"] #page-header.nav-fixed #nav .menus_item .menus_item_child li a.site-page.child {
  color: #e0e0e0 !important;
}

[data-theme="dark"] #nav .menus_item .menus_item_child li a.site-page.child:hover {
  background: rgba(73, 177, 245, 0.2) !important;
  color: #49b1f5 !important;
}

#nav .site-page {
  font-size: 17px;    /* 菜单项和搜索 */
}
